FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL := FALSE;
END_VAR
VAR
    state        : INT;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
END_VAR

openBtn  := openBtn AND NOT prevOpenBtn;
closeBtn := closeBtn AND NOT prevCloseBtn;
prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;

CASE state OF
    0: (* IDLE *)
        IF openBtn AND NOT openLimit THEN
            state    := 1;
            motorUp   := TRUE;
            motorDown := FALSE;
        ELSIF closeBtn AND NOT closeLimit THEN
            state    := 2;
            motorUp   := FALSE;
            motorDown := TRUE;
        ELSE
            motorUp   := FALSE;
            motorDown := FALSE;
        END_IF

    1: (* OPENING *)
        motorUp   := TRUE;
        motorDown := FALSE;
        IF openLimit THEN
            state    := 0;
            motorUp   := FALSE;
            motorDown := FALSE;
        ELSIF obstacle THEN
            state    := 3;
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
        END_IF

    2: (* CLOSING *)
        motorUp   := FALSE;
        motorDown := TRUE;
        IF closeLimit THEN
            state    := 0;
            motorUp   := FALSE;
            motorDown := FALSE;
        ELSIF obstacle THEN
            state    := 1;
            motorUp   := TRUE;
            motorDown := FALSE;
        END_IF

    3: (* FAULT *)
        motorUp   := FALSE;
        motorDown := FALSE;
        IF openBtn AND closeBtn THEN
            state    := 0;
            errorFlag := FALSE;
        END_IF

END_CASE;

END_FUNCTION_BLOCK
